function makeDemoPositions(opts: { uid: () => string }): Position[] {
  const mk = (n: number, w: number, h: number): Position => ({
    id: Models.asPositionId(opts.uid()),
    positionRef: `W-${String(n).padStart(3, "0")}`,
    qty: 1,
    itemPrice: 1250 + n * 175,
    roomName: "",
    widthMm: w,
    heightMm: h,
    fieldsX: 1,
    fieldsY: 1,
    insertion: "Fixed",
    cellInsertions: { "0,0": "Fixed" },
    positionType: "Window",
    useEstimateDefaults: true,
    overrides: {},
  });

  return [
    mk(1, 1000, 1200),
    mk(2, 900, 900),
    mk(3, 1200, 1050),
    mk(4, 800, 2100),
    mk(5, 1500, 1200),
  ];
}

function makeDemoEstimate(opts: { uid: () => string }, n: number): Estimate {
  const year = new Date().getFullYear();
  const base = `${year}-90${String(n).padStart(2, "0")}`;

  return {
    id: Models.asEstimateId(opts.uid()),
    estimateRef: base,
    baseEstimateRef: base,
    revisionNo: 0,
        status: "Draft" as const,
    estimatedOrderMonth: ORDER_MONTHS[(n - 1) % ORDER_MONTHS.length],
    estimatedOrderYear: year + Math.floor((n - 1) / ORDER_MONTHS.length),
    defaults: makeDefaultEstimateDefaults(),
    positions: makeDemoPositions(opts),
  };
}

