    const area = randFrom(["SS", "CM", "RM", "CO", "IG"]);
    return `${area}${randInt(1, 9)} ${randInt(1, 9)}${randFrom(["A", "B", "C", "D", "E", "F", "G", "H", "J", "K"])}${randFrom(["A", "B", "C", "D", "E", "F", "G", "H", "J", "K"])}`;
